/* ============================================
   OpenLearnHub — Shared Styles
   Editorial, Modern, Minimal
   ============================================ */

@import url('https://fonts.googleapis.com/css2?family=Space+Grotesk:wght@400;500;600;700&family=Plus+Jakarta+Sans:ital,wght@0,400;0,500;0,600;0,700;1,400&display=swap');

*, *::before, *::after {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

:root {
  --navy: #0a0a23;
  --navy-light: #1b1b32;
  --gold: #feac32;
  --gold-hover: #f4c563;
  --blue: #002ead;
  --blue-hover: #1a3fb5;
  --white: #ffffff;
  --off-white: #f5f6f7;
  --light-gray: #eceef0;
  --medium-gray: #d0d0d5;
  --dark-gray: #3b3b4f;
  --text-primary: #1b1b32;
  --text-secondary: #4a4a62;
  --text-muted: #6a6a7e;
  --card-bg: #ffffff;
  --body-bg: #f5f6f7;
  --shadow-sm: 0 1px 3px rgba(0,0,0,0.06), 0 1px 2px rgba(0,0,0,0.04);
  --shadow-md: 0 4px 12px rgba(0,0,0,0.08), 0 2px 4px rgba(0,0,0,0.04);
  --shadow-lg: 0 12px 32px rgba(0,0,0,0.1), 0 4px 8px rgba(0,0,0,0.06);
  --transition: 0.25s cubic-bezier(0.4, 0, 0.2, 1);
  --radius: 6px;
  --radius-lg: 12px;
  --max-width: 1100px;
  --header-height: 60px;
}

html {
  scroll-behavior: smooth;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  font-family: 'Plus Jakarta Sans', system-ui, -apple-system, sans-serif;
  font-size: 16px;
  line-height: 1.6;
  color: var(--text-primary);
  background-color: var(--body-bg);
  min-height: 100vh;
}

h1, h2, h3, h4, h5, h6 {
  font-family: 'Space Grotesk', system-ui, sans-serif;
  font-weight: 700;
  line-height: 1.2;
  color: var(--text-primary);
}

a {
  color: var(--blue);
  text-decoration: none;
  transition: color var(--transition);
}
a:hover {
  color: var(--blue-hover);
}

img {
  max-width: 100%;
  display: block;
}

/* ---- Grain Overlay ---- */
body::before {
  content: '';
  position: fixed;
  top: 0; left: 0; right: 0; bottom: 0;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 256 256' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='noise'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.9' numOctaves='4' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23noise)' opacity='0.03'/%3E%3C/svg%3E");
  pointer-events: none;
  z-index: 9999;
  opacity: 0.4;
}

/* ============================================
   HEADER
   ============================================ */

.site-header {
  background: var(--navy);
  position: sticky;
  top: 0;
  z-index: 1000;
  border-bottom: 1px solid rgba(255,255,255,0.08);
}

.header-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
  height: var(--header-height);
  display: flex;
  align-items: center;
  gap: 20px;
}

.logo {
  display: flex;
  align-items: center;
  gap: 10px;
  color: var(--white);
  font-family: 'Space Grotesk', sans-serif;
  font-weight: 700;
  font-size: 18px;
  text-decoration: none;
  flex-shrink: 0;
  letter-spacing: -0.02em;
}

.logo-icon {
  width: 32px;
  height: 32px;
  background: var(--gold);
  border-radius: 6px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: 700;
  color: var(--navy);
  font-size: 16px;
}

.search-bar {
  flex: 1;
  max-width: 440px;
  position: relative;
}

.search-bar input {
  width: 100%;
  height: 36px;
  padding: 0 14px 0 36px;
  border: 1px solid rgba(255,255,255,0.15);
  border-radius: 6px;
  background: rgba(255,255,255,0.08);
  color: var(--white);
  font-size: 13px;
  font-family: inherit;
  outline: none;
  transition: border-color var(--transition), background var(--transition);
}

.search-bar input::placeholder {
  color: rgba(255,255,255,0.45);
}

.search-bar input:focus {
  border-color: var(--gold);
  background: rgba(255,255,255,0.12);
}

.search-bar svg {
  position: absolute;
  left: 10px;
  top: 50%;
  transform: translateY(-50%);
  color: rgba(255,255,255,0.4);
  width: 16px;
  height: 16px;
}

.nav-links {
  display: flex;
  align-items: center;
  gap: 6px;
  flex-shrink: 0;
}

.nav-links a {
  color: rgba(255,255,255,0.8);
  font-size: 14px;
  font-weight: 500;
  padding: 6px 14px;
  border-radius: 6px;
  transition: color var(--transition), background var(--transition);
  text-decoration: none;
}

.nav-links a:hover {
  color: var(--white);
  background: rgba(255,255,255,0.08);
}

.nav-links a.nav-donate {
  background: var(--gold);
  color: var(--navy);
  font-weight: 600;
}

.nav-links a.nav-donate:hover {
  background: var(--gold-hover);
  color: var(--navy);
}

/* Hamburger */
.hamburger {
  display: none;
  flex-direction: column;
  gap: 5px;
  background: none;
  border: none;
  cursor: pointer;
  padding: 6px;
  flex-shrink: 0;
}

.hamburger span {
  display: block;
  width: 22px;
  height: 2px;
  background: var(--white);
  border-radius: 2px;
  transition: transform var(--transition), opacity var(--transition);
}

.hamburger.active span:nth-child(1) {
  transform: translateY(7px) rotate(45deg);
}
.hamburger.active span:nth-child(2) {
  opacity: 0;
}
.hamburger.active span:nth-child(3) {
  transform: translateY(-7px) rotate(-45deg);
}

/* Mobile Menu */
.mobile-menu {
  display: none;
  background: var(--navy-light);
  border-top: 1px solid rgba(255,255,255,0.08);
}

.mobile-menu.open {
  display: block;
}

.mobile-menu a {
  display: block;
  padding: 14px 24px;
  color: rgba(255,255,255,0.85);
  font-size: 15px;
  font-weight: 500;
  border-bottom: 1px solid rgba(255,255,255,0.06);
  text-decoration: none;
  transition: background var(--transition);
}

.mobile-menu a:hover {
  background: rgba(255,255,255,0.05);
  color: var(--white);
}

/* ============================================
   BANNER
   ============================================ */

.banner {
  background: var(--gold);
  text-align: center;
  padding: 10px 24px;
}

.banner a {
  color: var(--navy);
  font-weight: 600;
  font-size: 14px;
  text-decoration: none;
  letter-spacing: 0.01em;
}

.banner a:hover {
  text-decoration: underline;
  color: var(--navy);
}

/* ============================================
   CONTAINER / LAYOUT
   ============================================ */

.container {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: 0 24px;
}

.page-content {
  padding: 40px 0 60px;
}

/* ============================================
   FEATURED ARTICLE
   ============================================ */

.featured-article {
  margin-bottom: 48px;
}

.featured-card {
  position: relative;
  border-radius: var(--radius-lg);
  overflow: hidden;
  background: var(--navy);
  display: grid;
  grid-template-columns: 1fr 1fr;
  min-height: 340px;
  box-shadow: var(--shadow-lg);
  transition: transform var(--transition), box-shadow var(--transition);
  text-decoration: none;
  color: var(--white);
}

.featured-card:hover {
  transform: translateY(-3px);
  box-shadow: 0 16px 40px rgba(0,0,0,0.15);
  color: var(--white);
}

.featured-thumb {
  position: relative;
  overflow: hidden;
}

.featured-thumb .thumb-gradient {
  width: 100%;
  height: 100%;
  object-fit: cover;
  display: block;
}

.featured-body {
  padding: 40px;
  display: flex;
  flex-direction: column;
  justify-content: center;
}

.featured-body .tag {
  margin-bottom: 16px;
}

.featured-body h2 {
  font-size: 28px;
  color: var(--white);
  margin-bottom: 20px;
  line-height: 1.25;
  letter-spacing: -0.02em;
}

.featured-meta {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-top: auto;
}

.featured-meta .author-name {
  color: rgba(255,255,255,0.8);
  font-size: 14px;
  font-weight: 500;
}

.featured-meta .timestamp {
  color: rgba(255,255,255,0.5);
  font-size: 13px;
}

.featured-meta .dot {
  color: rgba(255,255,255,0.3);
  font-size: 12px;
}

/* ============================================
   TAGS
   ============================================ */

.tag {
  display: inline-block;
  padding: 4px 10px;
  border-radius: 4px;
  font-size: 12px;
  font-weight: 600;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  text-decoration: none;
  transition: opacity var(--transition);
}

.tag:hover {
  opacity: 0.85;
}

.tag-ai { background: #e8d5f5; color: #6b21a8; }
.tag-web-scraping { background: #d1fae5; color: #065f46; }
.tag-databases { background: #fee2e2; color: #991b1b; }
.tag-elasticsearch { background: #dbeafe; color: #1e40af; }
.tag-data-engineering { background: #fef3c7; color: #92400e; }
.tag-ai-automation { background: #ede9fe; color: #5b21b6; }
.tag-python { background: #d1fae5; color: #047857; }
.tag-nodejs { background: #dcfce7; color: #166534; }
.tag-google-sheets { background: #d1fae5; color: #065f46; }
.tag-cloud { background: #dbeafe; color: #1d4ed8; }
.tag-css { background: #fce7f3; color: #9d174d; }
.tag-general { background: #f3f4f6; color: #374151; }

/* ============================================
   ARTICLE GRID
   ============================================ */

.section-title {
  font-size: 24px;
  margin-bottom: 28px;
  letter-spacing: -0.02em;
}

.article-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 28px;
  margin-bottom: 40px;
}

.article-card {
  background: var(--card-bg);
  border-radius: var(--radius-lg);
  overflow: hidden;
  box-shadow: var(--shadow-sm);
  transition: transform var(--transition), box-shadow var(--transition);
  text-decoration: none;
  color: inherit;
  display: flex;
  flex-direction: column;
}

.article-card:hover {
  transform: translateY(-4px);
  box-shadow: var(--shadow-lg);
  color: inherit;
}

.card-thumb {
  height: 180px;
  position: relative;
  overflow: hidden;
}

.card-thumb .thumb-bg {
  width: 100%;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 48px;
  opacity: 0.2;
}

.card-thumb .tag {
  position: absolute;
  top: 12px;
  left: 12px;
  z-index: 2;
}

.card-body {
  padding: 20px;
  flex: 1;
  display: flex;
  flex-direction: column;
}

.card-body h3 {
  font-size: 17px;
  font-weight: 600;
  line-height: 1.35;
  margin-bottom: 16px;
  color: var(--text-primary);
  letter-spacing: -0.01em;
}

.card-meta {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-top: auto;
}

.avatar {
  width: 32px;
  height: 32px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 12px;
  font-weight: 700;
  color: var(--white);
  flex-shrink: 0;
}

.card-meta-text .author-name {
  font-size: 13px;
  font-weight: 600;
  color: var(--text-primary);
  display: block;
  line-height: 1.3;
}

.card-meta-text .timestamp {
  font-size: 12px;
  color: var(--text-muted);
  display: block;
  line-height: 1.3;
}

/* Thumb gradients per category */
.thumb-ai { background: linear-gradient(135deg, #667eea 0%, #764ba2 100%); }
.thumb-web-scraping { background: linear-gradient(135deg, #11998e 0%, #38ef7d 100%); }
.thumb-databases { background: linear-gradient(135deg, #f093fb 0%, #f5576c 100%); }
.thumb-elasticsearch { background: linear-gradient(135deg, #4facfe 0%, #00f2fe 100%); }
.thumb-data-engineering { background: linear-gradient(135deg, #fa709a 0%, #fee140 100%); }
.thumb-ai-automation { background: linear-gradient(135deg, #a18cd1 0%, #fbc2eb 100%); }
.thumb-python { background: linear-gradient(135deg, #30cfd0 0%, #330867 100%); }
.thumb-nodejs { background: linear-gradient(135deg, #a8e063 0%, #56ab2f 100%); }
.thumb-google-sheets { background: linear-gradient(135deg, #0ba360 0%, #3cba92 100%); }
.thumb-cloud { background: linear-gradient(135deg, #2196f3 0%, #21cbf3 100%); }
.thumb-css { background: linear-gradient(135deg, #e233ff 0%, #ff6b6b 100%); }

/* ============================================
   LOAD MORE
   ============================================ */

.load-more-container {
  text-align: center;
  padding: 20px 0;
}

.load-more-btn {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 14px 36px;
  background: var(--navy);
  color: var(--white);
  border: none;
  border-radius: var(--radius);
  font-size: 15px;
  font-weight: 600;
  font-family: inherit;
  cursor: pointer;
  transition: background var(--transition), transform var(--transition);
}

.load-more-btn:hover {
  background: var(--navy-light);
  transform: translateY(-1px);
}

.hidden-cards {
  display: none;
}

/* ============================================
   TAG PAGE SPECIFIC
   ============================================ */

.tag-page-header {
  padding: 40px 0 20px;
}

.tag-page-header h1 {
  font-size: 36px;
  margin-bottom: 6px;
  letter-spacing: -0.03em;
}

.tag-page-header .post-count {
  font-size: 16px;
  color: var(--text-muted);
  font-weight: 400;
}

/* Popular Tags */
.popular-tags-section {
  margin-bottom: 40px;
}

.popular-tags-section h3 {
  font-size: 14px;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--text-muted);
  margin-bottom: 14px;
  font-weight: 600;
}

.popular-tags-row {
  display: flex;
  flex-wrap: wrap;
  gap: 10px;
}

.popular-tag {
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 8px 16px;
  background: var(--white);
  border: 1px solid var(--light-gray);
  border-radius: 100px;
  font-size: 13px;
  font-weight: 500;
  color: var(--text-primary);
  text-decoration: none;
  transition: border-color var(--transition), box-shadow var(--transition);
}

.popular-tag:hover {
  border-color: var(--blue);
  box-shadow: var(--shadow-sm);
  color: var(--blue);
}

.popular-tag .count {
  font-size: 12px;
  color: var(--text-muted);
  font-weight: 400;
}

/* ============================================
   LEARN PAGE
   ============================================ */

.welcome-section {
  background: var(--white);
  border-radius: var(--radius-lg);
  padding: 40px;
  margin-bottom: 40px;
  box-shadow: var(--shadow-sm);
  text-align: center;
}

.welcome-section h1 {
  font-size: 32px;
  margin-bottom: 12px;
  letter-spacing: -0.03em;
}

.welcome-section p {
  color: var(--text-secondary);
  font-size: 16px;
  margin-bottom: 20px;
}

.btn-primary {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 12px 28px;
  background: var(--gold);
  color: var(--navy);
  border: none;
  border-radius: var(--radius);
  font-size: 15px;
  font-weight: 600;
  font-family: inherit;
  cursor: pointer;
  text-decoration: none;
  transition: background var(--transition), transform var(--transition);
}

.btn-primary:hover {
  background: var(--gold-hover);
  color: var(--navy);
  transform: translateY(-1px);
}

.curriculum-section {
  margin-bottom: 48px;
}

.curriculum-section h2 {
  font-size: 22px;
  margin-bottom: 20px;
  letter-spacing: -0.02em;
}

.cert-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.cert-item {
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 16px 20px;
  background: var(--white);
  border-radius: var(--radius);
  box-shadow: var(--shadow-sm);
  transition: box-shadow var(--transition), transform var(--transition);
  cursor: pointer;
  text-decoration: none;
  color: var(--text-primary);
}

.cert-item:hover {
  box-shadow: var(--shadow-md);
  transform: translateX(4px);
  color: var(--text-primary);
}

.cert-icon {
  width: 40px;
  height: 40px;
  border-radius: 8px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 20px;
  flex-shrink: 0;
}

.cert-item span {
  font-weight: 600;
  font-size: 15px;
}

.challenge-card {
  background: linear-gradient(135deg, var(--navy) 0%, #1b1b50 100%);
  border-radius: var(--radius-lg);
  padding: 40px;
  color: var(--white);
  margin-bottom: 48px;
  text-align: center;
}

.challenge-card h2 {
  color: var(--white);
  font-size: 24px;
  margin-bottom: 10px;
}

.challenge-card p {
  color: rgba(255,255,255,0.7);
  margin-bottom: 24px;
  font-size: 16px;
}

.challenge-links {
  display: flex;
  gap: 14px;
  justify-content: center;
  flex-wrap: wrap;
}

.challenge-link {
  padding: 10px 22px;
  border-radius: var(--radius);
  font-size: 14px;
  font-weight: 600;
  text-decoration: none;
  transition: background var(--transition), transform var(--transition);
}

.challenge-link.primary {
  background: var(--gold);
  color: var(--navy);
}

.challenge-link.primary:hover {
  background: var(--gold-hover);
  color: var(--navy);
}

.challenge-link.secondary {
  background: rgba(255,255,255,0.1);
  color: var(--white);
  border: 1px solid rgba(255,255,255,0.2);
}

.challenge-link.secondary:hover {
  background: rgba(255,255,255,0.15);
  color: var(--white);
}

.resource-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 28px;
  margin-bottom: 48px;
}

.resource-card {
  background: var(--white);
  border-radius: var(--radius-lg);
  padding: 28px;
  box-shadow: var(--shadow-sm);
}

.resource-card h3 {
  font-size: 18px;
  margin-bottom: 16px;
  letter-spacing: -0.01em;
}

.resource-list {
  list-style: none;
  display: flex;
  flex-direction: column;
  gap: 8px;
}

.resource-list li a {
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 10px 14px;
  border-radius: var(--radius);
  font-size: 14px;
  font-weight: 500;
  color: var(--text-primary);
  transition: background var(--transition);
  text-decoration: none;
}

.resource-list li a:hover {
  background: var(--off-white);
  color: var(--blue);
}

.resource-list li a::before {
  content: '→';
  color: var(--gold);
  font-weight: 700;
}

.beta-badge {
  display: inline-block;
  padding: 2px 8px;
  border-radius: 4px;
  font-size: 10px;
  font-weight: 700;
  text-transform: uppercase;
  background: #fef3c7;
  color: #92400e;
  margin-left: 6px;
  letter-spacing: 0.05em;
}

/* ============================================
   DONATE PAGE
   ============================================ */

.donate-hero {
  background: linear-gradient(135deg, var(--navy) 0%, #0f0f3d 60%, #1a1a4e 100%);
  border-radius: var(--radius-lg);
  padding: 56px 48px;
  color: var(--white);
  text-align: center;
  margin-bottom: 48px;
  position: relative;
  overflow: hidden;
}

.donate-hero::before {
  content: '';
  position: absolute;
  top: -50%;
  right: -20%;
  width: 400px;
  height: 400px;
  background: radial-gradient(circle, rgba(254,172,50,0.12) 0%, transparent 70%);
  border-radius: 50%;
}

.donate-hero h1 {
  font-size: 40px;
  color: var(--white);
  margin-bottom: 16px;
  letter-spacing: -0.03em;
  position: relative;
}

.donate-hero p {
  font-size: 17px;
  color: rgba(255,255,255,0.8);
  max-width: 640px;
  margin: 0 auto 36px;
  line-height: 1.7;
  position: relative;
}

.amount-selector {
  display: flex;
  gap: 10px;
  justify-content: center;
  margin-bottom: 20px;
  position: relative;
}

.amount-btn {
  padding: 14px 28px;
  border: 2px solid rgba(255,255,255,0.2);
  border-radius: var(--radius);
  background: transparent;
  color: var(--white);
  font-size: 18px;
  font-weight: 700;
  font-family: inherit;
  cursor: pointer;
  transition: all var(--transition);
  min-width: 80px;
}

.amount-btn:hover {
  border-color: var(--gold);
}

.amount-btn.active {
  background: var(--gold);
  border-color: var(--gold);
  color: var(--navy);
}

.donation-text {
  font-size: 15px;
  color: rgba(255,255,255,0.7);
  margin-bottom: 28px;
  position: relative;
  min-height: 24px;
}

.donate-cta-btn {
  display: inline-block;
  padding: 16px 56px;
  background: var(--gold);
  color: var(--navy);
  border: none;
  border-radius: var(--radius);
  font-size: 18px;
  font-weight: 700;
  font-family: inherit;
  cursor: pointer;
  transition: background var(--transition), transform var(--transition);
  position: relative;
}

.donate-cta-btn:hover {
  background: var(--gold-hover);
  transform: translateY(-2px);
}

.donate-sub-label {
  font-size: 13px;
  color: rgba(255,255,255,0.5);
  margin-top: 12px;
  position: relative;
}

.donate-sub-label a {
  color: rgba(255,255,255,0.7);
  text-decoration: underline;
}

/* Benefits, Initiatives, Achievements */
.info-section {
  margin-bottom: 48px;
}

.info-section h2 {
  font-size: 26px;
  margin-bottom: 24px;
  letter-spacing: -0.02em;
}

.benefits-grid {
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 16px;
}

.benefit-card {
  display: flex;
  align-items: flex-start;
  gap: 14px;
  padding: 20px;
  background: var(--white);
  border-radius: var(--radius);
  box-shadow: var(--shadow-sm);
}

.benefit-icon {
  width: 40px;
  height: 40px;
  border-radius: 10px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 20px;
  flex-shrink: 0;
  background: #fef3c7;
}

.benefit-card p {
  font-size: 14px;
  color: var(--text-secondary);
  line-height: 1.5;
}

.initiatives-list {
  list-style: none;
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: 12px;
}

.initiative-item {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 18px 20px;
  background: var(--white);
  border-radius: var(--radius);
  box-shadow: var(--shadow-sm);
  font-size: 14px;
  font-weight: 500;
}

.initiative-item::before {
  content: '▸';
  color: var(--gold);
  font-size: 18px;
  font-weight: 700;
  flex-shrink: 0;
}

.stats-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 16px;
}

.stat-card {
  background: var(--white);
  border-radius: var(--radius-lg);
  padding: 28px 20px;
  text-align: center;
  box-shadow: var(--shadow-sm);
  transition: transform var(--transition);
}

.stat-card:hover {
  transform: translateY(-2px);
}

.stat-number {
  font-family: 'Space Grotesk', sans-serif;
  font-size: 32px;
  font-weight: 700;
  color: var(--navy);
  line-height: 1;
  margin-bottom: 8px;
}

.stat-label {
  font-size: 13px;
  color: var(--text-muted);
  line-height: 1.4;
}

/* FAQ Accordion */
.faq-section {
  margin-bottom: 48px;
}

.faq-section h2 {
  font-size: 26px;
  margin-bottom: 24px;
  letter-spacing: -0.02em;
}

.faq-list {
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.faq-item {
  background: var(--white);
  border-radius: var(--radius);
  box-shadow: var(--shadow-sm);
  overflow: hidden;
}

.faq-question {
  width: 100%;
  padding: 18px 22px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 16px;
  background: none;
  border: none;
  cursor: pointer;
  font-size: 15px;
  font-weight: 600;
  font-family: inherit;
  color: var(--text-primary);
  text-align: left;
  transition: color var(--transition);
}

.faq-question:hover {
  color: var(--blue);
}

.faq-chevron {
  width: 20px;
  height: 20px;
  flex-shrink: 0;
  transition: transform var(--transition);
  color: var(--text-muted);
}

.faq-item.open .faq-chevron {
  transform: rotate(180deg);
}

.faq-answer {
  max-height: 0;
  overflow: hidden;
  transition: max-height 0.3s ease;
}

.faq-answer-inner {
  padding: 0 22px 18px;
  font-size: 14px;
  color: var(--text-secondary);
  line-height: 1.7;
}

/* ============================================
   FOOTER
   ============================================ */

.site-footer {
  background: var(--navy);
  color: rgba(255,255,255,0.7);
