  margin-bottom: 36px;
  color: rgba(255,255,255,0.6);
}

.footer-grid {
  display: grid;
  grid-template-columns: 2fr 1fr;
  gap: 48px;
  margin-bottom: 36px;
}

.footer-section h4 {
  font-size: 13px;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: var(--gold);
  margin-bottom: 16px;
  font-weight: 600;
}

.footer-tags {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.footer-tags a {
  display: inline-block;
  padding: 6px 14px;
  background: rgba(255,255,255,0.06);
  border-radius: 100px;
  font-size: 13px;
  color: rgba(255,255,255,0.6);
  text-decoration: none;
  transition: background var(--transition), color var(--transition);
}

.footer-tags a:hover {
  background: rgba(255,255,255,0.1);
  color: var(--white);
}

.footer-links {
  display: flex;
  flex-wrap: wrap;
  gap: 6px 16px;
}

.footer-links a {
  font-size: 13px;
  color: rgba(255,255,255,0.6);
  text-decoration: none;
  transition: color var(--transition);
}

.footer-links a:hover {
  color: var(--white);
}

.footer-bottom {
  border-top: 1px solid rgba(255,255,255,0.08);
  padding-top: 24px;
  font-size: 13px;
  color: rgba(255,255,255,0.4);
}

/* ============================================
   ANIMATIONS
   ============================================ */

@keyframes fadeInUp {
  from {
    opacity: 0;
    transform: translateY(20px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.animate-in {
  animation: fadeInUp 0.5s ease forwards;
  opacity: 0;
}

.article-card:nth-child(1) { animation-delay: 0.05s; }
.article-card:nth-child(2) { animation-delay: 0.1s; }
.article-card:nth-child(3) { animation-delay: 0.15s; }
.article-card:nth-child(4) { animation-delay: 0.2s; }
.article-card:nth-child(5) { animation-delay: 0.25s; }
.article-card:nth-child(6) { animation-delay: 0.3s; }

/* ============================================
   RESPONSIVE
   ============================================ */

@media (max-width: 1024px) {
  .article-grid {
    grid-template-columns: repeat(2, 1fr);
    gap: 20px;
  }
  .stats-grid {
    grid-template-columns: repeat(2, 1fr);
  }
  .resource-grid {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 768px) {
  .nav-links {
    display: none;
  }
  .hamburger {
    display: flex;
  }
  .search-bar {
    max-width: none;
  }
  .featured-card {
    grid-template-columns: 1fr;
    min-height: auto;
  }
  .featured-thumb {
    height: 200px;
  }
  .featured-body {
    padding: 24px;
  }
  .featured-body h2 {
    font-size: 22px;
  }
  .article-grid {
    grid-template-columns: 1fr;
    gap: 16px;
  }
  .card-thumb {
    height: 160px;
  }
  .tag-page-header h1 {
    font-size: 28px;
  }
  .popular-tags-row {
    overflow-x: auto;
    flex-wrap: nowrap;
    padding-bottom: 8px;
    -webkit-overflow-scrolling: touch;
  }
  .popular-tag {
    flex-shrink: 0;
  }
  .welcome-section {
    padding: 28px 20px;
  }
  .welcome-section h1 {
    font-size: 26px;
  }
  .donate-hero {
    padding: 36px 24px;
  }
  .donate-hero h1 {
    font-size: 30px;
  }
  .amount-selector {
    flex-wrap: wrap;
  }
  .amount-btn {
    min-width: 70px;
    padding: 12px 20px;
    font-size: 16px;
  }
  .benefits-grid {
    grid-template-columns: 1fr;
  }
  .initiatives-list {
    grid-template-columns: 1fr;
  }
  .stats-grid {
    grid-template-columns: repeat(2, 1fr);
  }
  .footer-grid {
    grid-template-columns: 1fr;
    gap: 28px;
  }
  .container {
    padding: 0 16px;
  }
  .page-content {
    padding: 28px 0 40px;
  }
  .section-title {
    font-size: 20px;
  }
}

@media (max-width: 480px) {
  .header-inner {
    padding: 0 16px;
    gap: 12px;
  }
  .logo span {
    display: none;
  }
  .featured-body h2 {
    font-size: 19px;
  }
  .donate-hero h1 {
    font-size: 26px;
  }
  .stats-grid {
    grid-template-columns: 1fr 1fr;
    gap: 10px;
  }
  .stat-number {
    font-size: 26px;
  }
}

